    double const shift_x = BeamSizeMonitorData_get__shift_x(el);
    double const shift_y = BeamSizeMonitorData_get__shift_y(el);
    double const shift_s = BeamSizeMonitorData_get__shift_s(el);
    double const rot_x_rad = BeamSizeMonitorData_get__rot_x_rad(el);
    double const rot_y_rad = BeamSizeMonitorData_get__rot_y_rad(el);
    double const rot_s_rad_no_frame = BeamSizeMonitorData_get__rot_s_rad_no_frame(el);
    double const length = 0.;
    ;
    double const anchor = BeamSizeMonitorData_get_rot_shift_anchor(el);
    int8_t const backtrack = LocalParticle_check_track_flag(part0, XS_FLAG_BACKTRACK);

    /* Spin tracking is disabled by the synrad compile flag */
