typedef   struct ExciterData_s * ExciterData;
 static inline ExciterData ExciterData_getp(ExciterData restrict  obj){
  int64_t offset=0;
  return (ExciterData)(( char*) obj+offset);
}
 static inline int64_t ExciterData_get_order(const ExciterData restrict  obj){
  int64_t offset=0;
  offset+=8;
  return *( int64_t*)(( char*) obj+offset);
}
 static inline void ExciterData_set_order(ExciterData restrict  obj, int64_t value){
  int64_t offset=0;
  offset+=8;
  *( int64_t*)(( char*) obj+offset)=value;
}
 static inline  int64_t* ExciterData_getp_order(ExciterData restrict  obj){
  int64_t offset=0;
  offset+=8;
  return ( int64_t*)(( char*) obj+offset);
}
 static inline int64_t ExciterData_get_nsamples(const ExciterData restrict  obj){
  int64_t offset=0;
  offset+=16;
  return *( int64_t*)(( char*) obj+offset);
}
 static inline void ExciterData_set_nsamples(ExciterData restrict  obj, int64_t value){
  int64_t offset=0;
  offset+=16;
  *( int64_t*)(( char*) obj+offset)=value;
}
 static inline  int64_t* ExciterData_getp_nsamples(ExciterData restrict  obj){
  int64_t offset=0;
  offset+=16;
  return ( int64_t*)(( char*) obj+offset);
}
 static inline double ExciterData_get_sampling_frequency(const ExciterData restrict  obj){
  int64_t offset=0;
  offset+=24;
  return *( double*)(( char*) obj+offset);
}
 static inline void ExciterData_set_sampling_frequency(ExciterData restrict  obj, double value){
  int64_t offset=0;
  offset+=24;
  *( double*)(( char*) obj+offset)=value;
}
 static inline  double* ExciterData_getp_sampling_frequency(ExciterData restrict  obj){
  int64_t offset=0;
  offset+=24;
  return ( double*)(( char*) obj+offset);
}
 static inline double ExciterData_get_frev(const ExciterData restrict  obj){
  int64_t offset=0;
  offset+=32;
  return *( double*)(( char*) obj+offset);
}
