    double const shift_x = DriftSliceData_get__shift_x(el);
    double const shift_y = DriftSliceData_get__shift_y(el);
    double const shift_s = DriftSliceData_get__shift_s(el);
    double const rot_x_rad = DriftSliceData_get__rot_x_rad(el);
    double const rot_y_rad = DriftSliceData_get__rot_y_rad(el);
    double const rot_s_rad_no_frame = DriftSliceData_get__rot_s_rad_no_frame(el);
    double const length = 0.;
    ;
    double const anchor = DriftSliceData_get_rot_shift_anchor(el);
    int8_t const backtrack = LocalParticle_check_track_flag(part0, XS_FLAG_BACKTRACK);

