 static inline
SynchrotronRadiationRecordData RBendData_getp_internal_record(RBendData el, LocalParticle* part){
    RecordIdentifier record_id = RBendData_getp__internal_record_id(el);
    if (RecordIdentifier_get_buffer_id(record_id) <= 0){
        return NULL;
    }
    else{
        return (SynchrotronRadiationRecordData) RecordIdentifier_getp_record(record_id, part);
    }
    }
    
