SynchrotronRadiationRecordData UniformSolenoidData_getp_internal_record(UniformSolenoidData el, LocalParticle* part){
    RecordIdentifier record_id = UniformSolenoidData_getp__internal_record_id(el);
    if (RecordIdentifier_get_buffer_id(record_id) <= 0){
        return NULL;
    }
    else{
        return (SynchrotronRadiationRecordData) RecordIdentifier_getp_record(record_id, part);
    }
    }
    
