               double const spin_x_1 = _cos_rot_s*spin_x_0 - _sin_rot_s*spin_y_0;
               double const spin_y_1 = _sin_rot_s*spin_x_0 + _cos_rot_s*spin_y_0;
               LocalParticle_set_spin_x(part, spin_x_1);
