/*---GENERATED GET RECORD FUNCTION---*/
 static inline
InteractionRecordData EverestBlockData_getp_internal_record(EverestBlockData el, LocalParticle* part){
    RecordIdentifier record_id = EverestBlockData_getp__internal_record_id(el);
    if (RecordIdentifier_get_buffer_id(record_id) <= 0){
        return NULL;
    }
    else{
        return (InteractionRecordData) RecordIdentifier_getp_record(record_id, part);
    }
    }
    
