 static inline
InteractionRecordData BaseCollimatorData_getp_internal_record(BaseCollimatorData el, LocalParticle* part){
    RecordIdentifier record_id = BaseCollimatorData_getp__internal_record_id(el);
    if (RecordIdentifier_get_buffer_id(record_id) <= 0){
        return NULL;
    }
    else{
        return (InteractionRecordData) RecordIdentifier_getp_record(record_id, part);
    }
    }
    
