/*---GENERATED GET RECORD FUNCTION---*/
 static inline
InteractionRecordData TransparentCollimatorData_getp_internal_record(TransparentCollimatorData el, LocalParticle* part){
    RecordIdentifier record_id = TransparentCollimatorData_getp__internal_record_id(el);
    if (RecordIdentifier_get_buffer_id(record_id) <= 0){
        return NULL;
    }
    else{
        return (InteractionRecordData) RecordIdentifier_getp_record(record_id, part);
    }
    }
    
