 static inline
InteractionRecordData BlackAbsorberData_getp_internal_record(BlackAbsorberData el, LocalParticle* part){
    RecordIdentifier record_id = BlackAbsorberData_getp__internal_record_id(el);
    if (RecordIdentifier_get_buffer_id(record_id) <= 0){
        return NULL;
    }
    else{
        return (InteractionRecordData) RecordIdentifier_getp_record(record_id, part);
    }
    }
    
