/*---GENERATED GET RECORD FUNCTION---*/
 static inline
InteractionRecordData TransparentCrystalData_getp_internal_record(TransparentCrystalData el, LocalParticle* part){
    RecordIdentifier record_id = TransparentCrystalData_getp__internal_record_id(el);
    if (RecordIdentifier_get_buffer_id(record_id) <= 0){
        return NULL;
    }
    else{
        return (InteractionRecordData) RecordIdentifier_getp_record(record_id, part);
    }
    }
    
